/** 中国省级行政区简化边界（Albers 等积圆锥投影，本地内置，无外网依赖） */
export interface ProvinceShape {
  name: string
  short: string
  adcode: number
  center: [number, number] | null
  path: string
}

export const CHINA_WIDTH = 1000
export const CHINA_HEIGHT = 841

/* Albers 等积圆锥投影（φ1=25°, φ2=47°, λ0=105°），与生成数据时一致 */
const RAD = Math.PI / 180
const N = 0.576985981680
const C = 1.309083430096
const RHO0 = 1.570762229609
const MIN_X = -0.411074673077
const MAX_Y = 0.519928377454
const SCALE = 1321.753521350905

/** 经纬度 → SVG 坐标（与地图 path 同一坐标系） */
export function projectLngLat(lng: number, lat: number): [number, number] {
  const phi = lat * RAD
  const lambda = lng * RAD
  const rho = Math.sqrt(C - 2 * N * Math.sin(phi)) / N
  const theta = N * (lambda - 105 * RAD)
  const x = rho * Math.sin(theta)
  const y = RHO0 - rho * Math.cos(theta)
  return [(x - MIN_X) * SCALE, (MAX_Y - y) * SCALE]
}

