const BY_SHORT = new Map(PROVINCES.map((item) => [item.short, item.name]))
const BY_NAME = new Map(PROVINCES.map((item) => [item.name, item]))

export function resolveProvinceName(value: string): string {
  if (!value) return ''
  if (BY_NAME.has(value)) return value
  return BY_SHORT.get(value.replace(/省|市$/, '')) ?? value
}

export function provinceByShort(short: string): ProvinceShape | undefined {
  return PROVINCES.find((item) => item.short === short)
}